import java.util.*;
import java.util.concurrent.locks.ReentrantLock;

public class ShardedLruCache<K, V> {
    private static final class Entry<V> {
        final V value;
        final long expireAtNanos;
        Entry(V v, long exp) { this.value = v; this.expireAtNanos = exp; }
    }

    private static final class Shard<K, V> {
        final ReentrantLock lock = new ReentrantLock();
        final LinkedHashMap<K, Entry<V>> map;
        Shard(int maxEntries) {
            this.map = new LinkedHashMap<>(16, 0.75f, true) {
                @Override
                protected boolean removeEldestEntry(Map.Entry<K, Entry<V>> eldest) {
                    return size() > maxEntries;
                }
            };
        }
    }

    private final Shard<K, V>[] shards;
    private final int mask;

    @SuppressWarnings("unchecked")
    public ShardedLruCache(int totalCapacity, int numShardsPowerOf2) {
        this.shards = new Shard[numShardsPowerOf2];
        this.mask = numShardsPowerOf2 - 1;
        int perShard = Math.max(1, totalCapacity / numShardsPowerOf2);
        for (int i = 0; i < numShardsPowerOf2; i++) shards[i] = new Shard<>(perShard);
    }

    private Shard<K, V> shardFor(K key) {
        int h = key.hashCode();
        h ^= (h >>> 16);
        return shards[h & mask];
    }

    public V get(K key) {
        Shard<K, V> s = shardFor(key);
        s.lock.lock();
        try {
            Entry<V> e = s.map.get(key);
            if (e == null) return null;
            if (System.nanoTime() > e.expireAtNanos) {
                s.map.remove(key);
                return null;
            }
            return e.value;
        } finally {
            s.lock.unlock();
        }
    }

    public void put(K key, V value, long ttlNanos) {
        Shard<K, V> s = shardFor(key);
        s.lock.lock();
        try {
            s.map.put(key, new Entry<>(value, System.nanoTime() + ttlNanos));
        } finally {
            s.lock.unlock();
        }
    }
}

// SIEVE read path: zero locks, zero list pointer mutations
public V getSieve(K key) {
    SieveNode<K, V> node = concurrentMap.get(key);
    if (node == null || node.isExpired()) return null;
    node.visited = true; // volatile write only if currently false!
    return node.value;
}

// W-TinyLFU admission check:
boolean admitToMain(long candidateHash, long mainVictimHash, CountMinSketch cms) {
    return cms.estimate(candidateHash) > cms.estimate(mainVictimHash);
}

ConcurrentHashMap<K, CompletableFuture<V>> inflight = new ConcurrentHashMap<>();

public CompletableFuture<V> getOrLoad(K key, Supplier<V> loader) {
    V cached = cache.get(key);
    if (cached != null) return CompletableFuture.completedFuture(cached);
    return inflight.computeIfAbsent(key, k -> CompletableFuture.supplyAsync(() -> {
        try {
            V val = loader.get();
            cache.put(k, val, ttlNanos);
            return val;
        } finally {
            inflight.remove(k);
        }
    }));
}
